program = '''def transform(grid):
    """Complete diagonal bands as a 2D periodic pattern."""
    h, w = len(grid), len(grid[0])
    bands = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                d = c - r
                if d in bands and bands[d] != value:
                    raise ValueError("inconsistent diagonal band")
                bands[d] = value
    # Each diagonal is one entry of the repeating sequence indexed by c-r.
    period = None
    for p in range(1, max(h, w) + 1):
        seq = {}
        for d, value in bands.items():
            residue = d % p
            if residue in seq and seq[residue] != value:
                break
            seq[residue] = value
        else:
            if len(seq) == p:
                period = p
                break
    if period is None:
        raise ValueError("could not infer a complete diagonal period")
    seq = {d % period: value for d, value in bands.items()}
    return [[seq[(c - r) % period] for c in range(w)] for r in range(h)]
'''
